    static double computeAngle(int[] p1, int[] p2, int[] p3) {
        double dot = 0, aLen = 0, bLen = 0;
        for (int i = 0; i < p1.length; i++) {
            double v1 = p2[i] - p1[i];
            double v2 = p3[i] - p1[i];
            dot += v1 * v2;
            aLen += v1 * v1;
            bLen += v2 * v2;
        }
        return 180 * Math.acos(dot / Math.sqrt(aLen * bLen)) / Math.PI;
    }

    static int readInt(DataInputStream dis) throws IOException {
        int ret = 0;
        boolean neg = false;
        byte c = dis.readByte();
        while (c <= ' ') {
            c = dis.readByte();
        }
        if (c == '-') {
            neg = true;
            c = dis.readByte();
        }
        do {
            ret = ret * 10 + c - '0';
        } while ((c = dis.readByte()) >= '0' && c <= '9');
        return neg ? -ret : ret;
    }
}
