#include <bits/stdc++.h>
using namespace std;

double computeAngle(const vector<int>& p1, const vector<int>& p2, const vector<int>& p3) {
    double dot = 0.0, aLen = 0.0, bLen = 0.0;
    for (int i = 0; i < p1.size(); i++) {
        double v1 = p2[i] - p1[i];
        double v2 = p3[i] - p1[i];
        dot += v1 * v2;
        aLen += v1 * v1;
        bLen += v2 * v2;
    }
    return 180.0 * acos(dot / sqrt(aLen * bLen)) / M_PI;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 20) {
        cout << 0 << "\n";
    } else {
        vector<vector<int>> points(n, vector<int>(5));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> points[i][j];
            }
        }
        vector<int> valid;
        for (int i = 0; i < n; i++) {
            bool isValid = true;
            for (int j = 0; j < n && isValid; j++) {
                if (i != j) {
                    for (int k = j + 1; k < n && isValid; k++) {
                        if (i != k) {
                            if (computeAngle(points[i], points[j], points[k]) < 90) {
                                isValid = false;
                            }
                        }
                    }
                }
            }
            if (isValid) {
                valid.push_back(i + 1);
            }
        }
        cout << valid.size() << "\n";
        for (int v : valid) {
            cout << v << "\n";
        }
    }
    return 0;
}
